#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
template <typename... Args>
void print_all(Args&&... args) {
  ((std::cout << args << " "), ...); // Fold expression for printing
  std::cout << std::endl;
}
template <typename T>
void process_data(const std::vector<T>& data) {
  for (const auto& item : data) {
    print_all(item, "processed");
  }
}
int main() {
  std::vector<std::string> strings = {"hello", "world", "C++"};
  std::vector<int> numbers = {1, 2, 3, 4, 5};
  process_data(strings);
  process_data(numbers);
  return 0;
}
